def evolve(state: str, offsets: list[int], t: int) -> str:
    if t == 0:
        return state

    n = len(state)
    mask = (1 << n) - 1
    lamps = int(state, 2)
    shifts = [d % n for d in offsets]

    while t:
        if t & 1:
            updated = 0
            for d in shifts:
                updated ^= ((lamps << d) | (lamps >> (n - d))) & mask
            lamps = updated

        t >>= 1
        # Over XOR, squaring the update doubles every offset.
        shifts = [(2 * d) % n for d in shifts]

    return format(lamps, f"0{n}b")
